# Verify the solution
def verify_coloring(n, coloring, clique_size):
    edge_index = {}
    edges = []
    idx = 0
    for i in range(n):
        for j in range(i+1, n):
            edge_index[(i,j)] = idx
            edges.append((i,j))
            idx += 1

    cliques = list(combinations(range(n), clique_size))

    for clique in cliques:
        clique_edges = []
        for i in range(len(clique)):
            for j in range(i+1, len(clique)):
                u, v = clique[i], clique[j]
                if u > v:
                    u, v = v, u
                clique_edges.append(edge_index[(u,v)])

        colors = [coloring[e] for e in clique_edges]
        if all(c == 0 for c in colors):
            return False, f"Monochromatic RED clique: {clique}"
        if all(c == 1 for c in colors):
            return False, f"Monochromatic BLUE clique: {clique}"

    return True, "Valid coloring!"

valid, msg = verify_coloring(21, coloring, 5)
print(f"Verification: {valid}")
print(f"Message: {msg}")
print(f"\nFull coloring ({len(coloring)} values):")
print(coloring)

from pysat.solvers import Glucose3
from itertools import combinations

n = 21
clique_size = 5

# Create edge index mapping
edge_index = {}
edges = []
idx = 0
for i in range(n):
    for j in range(i+1, n):
        edge_index[(i,j)] = idx
        edges.append((i,j))
        idx += 1

solver = Glucose3()
cliques = list(combinations(range(n), clique_size))

for clique in cliques:
    clique_edges = []
    for i in range(len(clique)):
        for j in range(i+1, len(clique)):
            u, v = clique[i], clique[j]
            if u > v:
                u, v = v, u
            clique_edges.append(edge_index[(u,v)] + 1)

    solver.add_clause(clique_edges)
    solver.add_clause([-v for v in clique_edges])

result = solver.solve()
print(f"SAT result: {result}")

if result:
    model = solver.get_model()
    coloring = [0] * len(edges)
    for lit in model:
        if lit > 0:
            coloring[lit - 1] = 1

    # Verify
    valid = True
    for clique in cliques:
        clique_edge_indices = []
        for i in range(len(clique)):
            for j in range(i+1, len(clique)):
                u, v = clique[i], clique[j]
                if u > v:
                    u, v = v, u
                clique_edge_indices.append(edge_index[(u,v)])

        colors = [coloring[e] for e in clique_edge_indices]
        if all(c == 0 for c in colors):
            valid = False
            print(f"FAIL: Monochromatic RED clique: {clique}")
            break
        if all(c == 1 for c in colors):
            valid = False
            print(f"FAIL: Monochromatic BLUE clique: {clique}")
            break

    if valid:
        print("VERIFIED: No monochromatic K_5!")
        print(f"Red: {coloring.count(0)}, Blue: {coloring.count(1)}")
        print("Solution:", coloring)
